// ===== تحضير المرشحين: تطبيق القواعد + تجهيز طلب ChatGPT =====
const cfg = $('الإعدادات (Config)').first().json;
const matchMode = (cfg.matchMode || 'contains').toLowerCase();

// 1) الكلمات الممنوعة من الشيت
const kwAgg = $('تجميع الكلمات').first().json.data || [];
const banned = [];
for (const row of kwAgg) {
  const v = Object.values(row).find(x => x != null && String(x).trim() !== '');
  if (v) banned.push(String(v).trim().toLowerCase());
}
const uniqueBanned = [...new Set(banned)].filter(Boolean);

// 2) نتائج searchStream
const raw = $input.all().map(i => i.json);
const results = [];
for (const b of raw) {
  if (Array.isArray(b?.results)) results.push(...b.results);
  else if (Array.isArray(b)) { for (const x of b) if (Array.isArray(x?.results)) results.push(...x.results); }
}

const norm = s => String(s || '').trim().toLowerCase();
const isMatch = (t, w) => matchMode === 'exact' ? t === w : t.includes(w);

const ruleDecisions = [];
const candidates = [];
const seen = new Set();
for (const r of results) {
  const term = norm(r?.searchTermView?.searchTerm);
  if (!term) continue;
  const campaignId = r?.campaign?.id;
  if (!campaignId) continue;
  const campaignName = r?.campaign?.name || '';
  const clicks = Number(r?.metrics?.clicks || 0);
  const cost = Number(r?.metrics?.costMicros || 0) / 1e6;
  const key = campaignId + '::' + term;
  if (seen.has(key)) continue;
  seen.add(key);
  const hit = uniqueBanned.find(w => isMatch(term, w));
  const base = { searchTerm: term, campaignId: String(campaignId), campaignName, clicks, cost };
  if (hit) ruleDecisions.push({ ...base, matchedWord: hit });
  else candidates.push(base);
}

// 3) تجهيز طلب ChatGPT (لغير المطابقين فقط)
const systemPrompt =
`أنت مصنّف احترافي لكلمات البحث (Search Terms) في حملات Google Ads.
مهمتك: لكل عبارة بحث قرّر هل نستبعدها (غير مناسبة للنشاط) أم نُبقيها.

نشاط الشركة:
${cfg.businessContext || ''}

أبقِ العبارة (exclude=false) إذا:
- بحث عن شركة/مزوّد في نفس المجال، أو نيّة مشاريع/شركات/مقاولات/تصميم داخلي/عقارات
- بحث بالمجال أو اسم الخدمة (سمارت هوم، منزل ذكي، تيار خفيف، أتمتة مباني، أنظمة أمن ومراقبة)
- ضمن السعودية

استبعد العبارة (exclude=true) إذا:
- وظائف/توظيف/رواتب/تدريب
- مجاني/شرح/كورس/DIY/طريقة عمل بنفسك
- منتج مفرد رخيص بدون نيّة مشروع أو منتجات لا تبيعها الشركة
- بحث معلومات/طلاب/تعريفات
- دولة خارج السعودية

كن متحفظاً: إن لم تكن متأكداً اجعل exclude=false مع confidence منخفض.`;

const userPrompt =
'صنّف العبارات التالية وأعد النتيجة بصيغة JSON فقط بالشكل: ' +
'{"results":[{"searchTerm":"العبارة كما هي","exclude":true او false,"reason":"سبب مختصر بالعربية","confidence":رقم من 0 الى 100}]}.\n\n' +
'العبارات:\n' + JSON.stringify(candidates.map(c => c.searchTerm));

const openaiBody = {
  model: 'gpt-4o-mini',
  temperature: 0,
  response_format: { type: 'json_object' },
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: userPrompt }
  ]
};

return [{ json: {
  businessContext: cfg.businessContext || '',
  candidates,
  ruleDecisions,
  candidatesCount: candidates.length,
  ruleMatchedCount: ruleDecisions.length,
  negateMode: (cfg.negateMode || 'searchTerm'),
  negativeMatchType: (cfg.negativeMatchType || 'EXACT'),
  openaiBody
} }];

// ===== دمج قرارات القواعد + ChatGPT وبناء صفوف المراجعة =====
const prep = $('تحضير المرشحين').first().json;
const now = new Date().toISOString();

// قراءة رد ChatGPT
let ai = [];
try {
  const content = $input.first().json?.choices?.[0]?.message?.content || '{}';
  const parsed = typeof content === 'string' ? JSON.parse(content) : content;
  ai = Array.isArray(parsed) ? parsed : (parsed.results || []);
} catch (e) { ai = []; }

// خريطة الميتريكس للمرشحين
const cmap = {};
for (const c of prep.candidates) cmap[c.searchTerm] = c;

const rows = [];

// صفوف القواعد (استبعاد مؤكد)
for (const r of prep.ruleDecisions) {
  rows.push({
    searchTerm: r.searchTerm,
    decision: 'exclude',
    source: 'rule',
    matchedWord: r.matchedWord,
    reason: 'مطابقة قاعدة: ' + r.matchedWord,
    confidence: 100,
    suggestedNegative: prep.negateMode === 'keyword' ? r.matchedWord : r.searchTerm,
    matchType: prep.negativeMatchType,
    campaignId: r.campaignId,
    campaignName: r.campaignName,
    clicks: r.clicks,
    cost: r.cost,
    date: now
  });
}

// صفوف ChatGPT (المستبعَد فقط)
for (const a of ai) {
  if (!a || a.exclude !== true) continue;
  const term = String(a.searchTerm || '').trim().toLowerCase();
  const m = cmap[term] || {};
  rows.push({
    searchTerm: term,
    decision: 'exclude',
    source: 'ai',
    matchedWord: '',
    reason: a.reason || '',
    confidence: Number(a.confidence || 0),
    suggestedNegative: term,
    matchType: prep.negativeMatchType,
    campaignId: m.campaignId || '',
    campaignName: m.campaignName || '',
    clicks: m.clicks || 0,
    cost: m.cost || 0,
    date: now
  });
}

if (rows.length === 0) {
  return [{ json: { searchTerm: '', decision: 'no-suggestions', source: '', matchedWord: '', reason: 'لا توجد اقتراحات في هذه الجولة', confidence: 0, suggestedNegative: '', matchType: '', campaignId: '', campaignName: '', clicks: 0, cost: 0, date: now } }];
}
return rows.map(r => ({ json: r }));
